extern fn parquet::read(path: String) -> DataFrame from "parquet.hpp";

let orders = parquet::read("/home/brj/code/polars-benchmark/data/tables/scale-10.0/orders.parquet") as DataFrame<{
    o_orderkey: Int64,
    o_orderpriority: String
}>;
