cli_streaming_ab.driver:
import subprocess,os,re,time,json,statistics,select
from pathlib import Path
workers={};logs={}
for name,stream in [('streaming','1'),('eager','0')]:
 env=os.environ.copy();env['IBEX_STREAM_SCAN']=stream
 logs[name]=open('/tmp/q12-cli-'+name+'.stderr','w')
 workers[name]=subprocess.Popen(['build-release/tools/ibex','--no-history','--plugin-path','build-release/tools'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=logs[name],text=True,env=env)
 workers[name].stdin.write(':timing on\n');workers[name].stdin.flush()
def call(name):
 p=workers[name];p.stdin.write(':run /tmp/q12-native-whole.ibex\n');p.stdin.flush();lines=[]
 while True:
  line=p.stdout.readline()
  if not line:raise RuntimeError(name+' stopped: '+''.join(lines))
  lines.append(line)
  m=re.match(r'^time:\s*([\d.]+)\s*(us|ms|s)',line)
  if m:
   assert 'MAIL' in ''.join(lines) and 'SHIP' in ''.join(lines)
   return float(m[1])*{'us':.001,'ms':1,'s':1000}[m[2]]
try:
 for name in workers:
  for _ in range(2):call(name)
 samples={n:[] for n in workers}
 for i in range(12):
  for name in (list(workers) if i%2==0 else list(reversed(workers))):samples[name].append(call(name))
finally:
 for p in workers.values():
  p.stdin.write(':quit\n');p.stdin.flush();p.stdin.close();p.wait(timeout=30)
 for f in logs.values():f.close()
r={'median_ms':{n:statistics.median(v) for n,v in samples.items()},'samples_ms':samples,'method':'same native Q12, two persistent CLI workers; IBEX_STREAM_SCAN=1 versus 0; two warmups, twelve alternating paired rounds','driver':Path(__file__).read_text()}
Path('/tmp/q12-cli-streaming-ab.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r['median_ms']))

