 if type(v).__name__=='Function' and str(v.function_data[0]).split('.')[-1]=='IsIn' and v.function_data[1] is False:
  c=self.visitor.view_expression(v.input[1])
  if type(c).__name__=='Literal' and c.value and all(x is not None for x in c.value):
   assert r._op=='case'
   if mode=='plain':return r._args[2]
   if mode=='no_false':
    expr=r._args[2]
    def strip(e):
     if e._op=='||':
      a,b=e._args
      if a._op=='lit' and a._args==(False,):return b
      return type(e)('||',(strip(a),b))
     return e
    return strip(expr)
 return r
