import subprocess

def lit(v):
 if isinstance(v,str):return json.dumps(v)
 if isinstance(v,bool):return str(v).lower()
 if isinstance(v,datetime.date):return 'date'+json.dumps(v.isoformat())
 return repr(v)
for name in ('case','plain','no_false','compact'):
 source=sources[name].split('\n',1)[1]
 binds=plans[name][2] if name!='compact' else cb
 pre=['extern fn parquet::read(path: String) -> DataFrame from "parquet.hpp";']
 pre += ['let '+k+' = '+lit(v)+';' for k,v in binds.items()]
 pre += ['let raw_orders = parquet::read('+json.dumps(str(root/'orders.parquet'))+');',
         'let raw_lineitem = parquet::read('+json.dumps(str(root/'lineitem.parquet'))+');']
 for k,v in binds.items():
  if v==str(root/'orders.parquet'):source=source.replace('parquet::read(^'+k+')','raw_orders')
  if v==str(root/'lineitem.parquet'):source=source.replace('parquet::read(^'+k+')','raw_lineitem')
 if name!='compact':
  filter_start=source.index('raw_lineitem[filter ')
  filter_end=source.index('][select',filter_start)+1
  phases={'line_filter':source[filter_start:filter_end],
          'join':source[:source.index('})[select')+2],
          'aggregate':source[:source.index('[update { `_ibex_sort_')]}
 else:
  fs=source.index('raw_lineitem[filter ');fe=source.index(']\non ',fs)+1
  phases={'line_filter':source[fs:fe], 'join':source[:source.index('})[select')+2],
          'aggregate':source[:source.index('[order')]}
 text='\n'.join(pre)+'\n'+''.join(':explain '+x.replace('\n',' ')+'\n' for x in phases.values())+':quit\n'
 Path('/tmp/q12-inspect-'+name+'.input').write_text(text)
 r=subprocess.run(['build-release/tools/ibex','--no-history','--plugin-path','build-release/tools'],input=text,text=True,capture_output=True)
 Path('/tmp/q12-inspect-'+name+'.txt').write_text(r.stdout+r.stderr)
 print(name,r.returncode,r.stdout[-4000:],r.stderr)
